{"file_path":"tree_building.go","content":"package tree

import (
	"errors"
	"fmt"
)

type Record struct {
	ID     int
	Parent int
}

type Node struct {
	ID       int
	Children []*Node
}

func Build(records []Record) (*Node, error) {
	if len(records) == 0 {
		return nil, nil
	}

	nodes := make([]*Node, len(records))
	seen := make([]bool, len(records))

	for _, record := range records {
		if record.ID < 0 || record.ID >= len(records) {
			return nil, fmt.Errorf("record ID %d out of range", record.ID)
		}
		if seen[record.ID] {
			return nil, fmt.Errorf("duplicate record with ID %d", record.ID)
		}
		seen[record.ID] = true

		if record.ID == 0 {
			if record.Parent != 0 {
				return nil, errors.New("root node must not have a parent")
			}
		} else if record.Parent >= record.ID {
			return nil, fmt.Errorf("record %d has invalid parent %d", record.ID, record.Parent)
		}

		nodes[record.ID] = &Node{ID: record.ID}
	}

	for id, ok := range seen {
		if !ok {
			return nil, fmt.Errorf("missing record with ID %d", id)
		}
	}

	for _, record := range records {
		if record.ID == 0 {
			continue
		}
		parent := nodes[record.Parent]
		parent.Children = append(parent.Children, nodes[record.ID])
	}

	return nodes[0], nil
}
"}

